"""Seventeen NEW body bindings from GT-M03, GT-S03 and GT-V03.

These profiles describe authored equipment, not a claim that campaign stock exists.
The complete source verdicts and original equipment records remain preserved.
"""
from copy import deepcopy
import re

def models():
    result={}
    def add(trade,code,family,gp,lb,ac,primary,replaceable,text,**limits):
        text=re.sub(r'(?<=[A-Za-z])(?=\d)|(?<=\d)(?=[A-Za-z])',' ',text)
        text=re.sub(r'([,;])(?=[A-Za-z0-9])',r'\1 ',text)
        mid=trade.lower()+'.'+family.lower().replace(' ','-')
        result[mid]={'id':mid,'trade':trade,'code':code,'family':family,
            'baselinePriceGp':gp,'baselineWeightLb':lb,'ordinaryMaximumStructuralHP':5,
            'structuralAC':ac,'equipmentGrade':'Standard','fixedDimensions':True,
            'automaticLargeScaling':False,'magical':True,'artifact':False,
            'attunementRequired':False,'charges':False,'resourceCost':0,
            'concentration':False,'separateMagicActivation':False,'requiredHands':2,
            'requiredOriginalPrimaryMembers':primary,'permittedSubordinateReplacements':replaceable,
            'operationalBodyText':text,'physicalLimits':limits,
            'sourceDecision':{'Mining':'GT-M03','Skinning':'GT-S03','Salvaging':'GT-V03'}[trade],
            'provenance':'NEW finite body binding; any reused mundane price/mass remains identified in the preserved source verdict'}
